REALS='https://doi.org/10.1109/WACV56688.2023.00198'
FIGURE='https://media.springernature.com/full/springer-static/image/art%3A10.1038%2Fs41592-023-02005-8/MediaObjects/41592_2023_2005_Fig1_HTML.png'
ARROW='<svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3 13 13 3M3 3h10v10"/></svg>'
def link(href,text,kind='text-link'):
    external=href.startswith('https:')
    return f'<a class="{kind}" href="{html.escape(href,quote=True)}"'+(' target="_blank" rel="noopener noreferrer"' if external else '')+f'>{text}<span class="arrow">{ARROW}</span></a>'
def feature(title,text,href,cls=''):
    return f'<a class="feature-link {cls}" href="{href}"><h2>{title}</h2><p>{text}</p><span class="arrow square">{ARROW}</span></a>'
NAV=[('Research',[('index.html','Home'),('vision.html','Vision'),('research.html','Our Science'),('publications.html','Publications'),('resources.html','Resources')]),('About',[('profile.html','Seungjae Han, PhD'),('profile.html#education','Education'),('profile.html#fellowships','Fellowships'),('profile.html#service','Professional Service')]),('Updates',[('news.html','News'),('publications.html#support','SUPPORT'),('publications.html#memristor','Analogue Computing'),('https://github.com/SteveJayH','GitHub')]),('Contact',[('contact.html','Contact'),('mailto:jay0118@kaist.ac.kr','Email'),(SCHOLAR,'Google Scholar'),('CV_SeungjaeHan_0707.pdf','Curriculum Vitae')])]
wordmark='<a class="wordmark" href="index.html" aria-label="Seungjae Han, home"><span><strong>SEUNGJAE</strong> HAN</span><small>KAIST · ELECTRICAL ENGINEERING</small></a>'
header='<a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="container navigation-bar">'+wordmark+'<details class="navigation"><summary class="menu-toggle" aria-label="Navigation menu" aria-controls="site-navigation"><span class="menu-lines" aria-hidden="true"><i></i><i></i><i></i></span></summary><nav class="menu-panel" id="site-navigation" aria-label="Main navigation"><div class="container menu-grid">'+''.join('<div><h2>'+title+'</h2>'+''.join(link(href,txt) for href,txt in items)+'</div>' for title,items in NAV)+'</div></nav></details></div></header>'
footer='<footer class="site-footer"><div class="container footer-grid"><div>'+wordmark+'<p>School of Electrical Engineering<br>KAIST, South Korea</p></div><nav class="footer-pages" aria-label="Footer navigation">'+''.join(f'<a href="{href}">{name}</a>' for href,name in [('index.html','Home'),('vision.html','Vision'),('research.html','Research'),('profile.html','About'),('publications.html','Publications'),('resources.html','Resources'),('news.html','News'),('contact.html','Contact')])+'</nav><div class="footer-links">'+link('mailto:jay0118@kaist.ac.kr','Email')+link(SCHOLAR,'Google Scholar')+link('CV_SeungjaeHan_0707.pdf','CV')+'</div></div></footer>'
def page(name,title,body,description):
    doc=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#982b34"><title>{title} | Seungjae Han</title><meta name="description" content="{html.escape(description,quote=True)}"><link rel="canonical" href="https://stevejayh.github.io/{'' if name=='index' else name+'.html'}"><link rel="preconnect" href="https://cdn.prod.website-files.com" crossorigin><link rel="preload" href="{FONT}" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="assets/site.css"><script src="assets/site.js" defer></script></head>
<body data-page="{name}">{header}<main id="main" tabindex="-1">{body}</main>{footer}</body></html>'''
    (OUT/f'{name}.html').write_text(doc)
def hero(eyebrow,title,desc='',extra=''):
    return '<section class="page-hero"><div class="container"><div class="hero-copy">'+(f'<p class="eyebrow">{eyebrow}</p>' if eyebrow else '')+f'<h1>{title}</h1>'+(f'<p class="hero-description">{desc}</p>' if desc else '')+extra+'</div></div></section>'
def figure():
    return f'<figure class="science-figure"><a href="{SUPPORT}" target="_blank" rel="noopener noreferrer"><img src="{FIGURE}" width="1200" height="1100" loading="lazy" alt="SUPPORT architecture and examples of denoising voltage imaging data, from Figure 1 of the 2023 paper."></a><figcaption>Eom, Han, Park et al., <a href="{SUPPORT}">Nature Methods (2023), Fig. 1</a>. <a href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a>.</figcaption></figure>'
home=hero('','Developing self-supervised learning methods to recover neural activity from fluorescence microscopy data.','I am Seungjae Han, a postdoctoral fellow at KAIST. I develop computational methods for neuroscience, working on self-supervised learning, image reconstruction, and the analysis of neural recordings.',link('research.html','Learn More','button-link'))
home+='<section class="section" id="vision"><div class="container split vision-split"><div><p class="eyebrow">Vision</p><h2 class="section-title">Connecting how images are acquired with how neural signals are recovered.</h2><p class="body-copy">My work brings together statistical estimation, machine learning, and fluorescence microscopy. The aim is to make neural activity measurements more reliable without requiring clean training images.</p>'+link('vision.html','Read the Vision','button-link')+'</div>'+figure()+'</div></section>'
home+='<section class="section purple" id="research"><div class="container split"><figure class="cover-figure"><a href="publications.html#support"><img src="nature_methods_cover.png" width="425" height="584" loading="lazy" alt="Nature Methods, October 2023 cover featuring SUPPORT."></a><figcaption>Nature Methods · October 2023</figcaption></figure><div><p class="eyebrow">Research</p><h2 class="section-title">Recovering fast signals from noisy data, and designing the algorithms that make this possible.</h2><p class="body-copy">Research topics include voltage imaging denoising, calcium imaging analysis, and self-supervised processing on analogue hardware.</p>'+link('research.html','Learn More','button-link')+'</div></div></section>'
home+='<section class="section gray" id="impact"><div class="container"><p class="eyebrow">Impact</p><div class="impact-grid"><article><h2 class="section-title">Denoising without losing fast neural dynamics.</h2><p>SUPPORT uses spatial and temporal information to denoise voltage imaging recordings.</p>'+link('publications.html#support','Nature Methods · 2023')+'</article><article><h2 class="section-title">Self-supervised processing on analogue hardware.</h2><p>A memristor-array platform combines video processing with self-calibration.</p>'+link('publications.html#memristor','Nature Electronics · 2025')+'</article></div></div></section>'
home+='<section class="section"><div class="container feature-grid">'+feature('Research','Methods for denoising, reconstruction, and the analysis of neural recordings.','research.html')+feature('About','Biography, education, appointments, fellowships, and academic service.','profile.html','teal')+feature('Publications','Journal articles, conference papers, and preprints.','publications.html','purple')+'</div></section>'
page('index','Home',home,'Seungjae Han at KAIST. Computational neuroscience, self-supervised learning, and fluorescence microscopy.')
vision=hero('Vision','Reliable measurements of neural activity.','I develop computational methods for neuroscience, with a focus on self-supervised learning and fluorescence microscopy.')
vision+='<section class="section"><div class="container split"><div><p class="eyebrow">Research direction</p><h2 class="section-title">Treating acquisition and analysis as parts of the same problem.</h2><p class="body-copy">My work spans algorithms and imaging pipelines. I am interested in methods that recover useful signals from the data an experiment can actually collect, rather than assuming that ideal training data are available.</p><p class="body-copy">This connects my work on voltage and calcium imaging with self-supervised network design and analogue video processing.</p>'+link('research.html','Research projects','button-link')+'</div>'+figure()+'</div></section>'
vision+='<section class="section gray"><div class="container"><p class="eyebrow">Focus</p><div class="impact-grid"><article><h2 class="section-title">Preserve the signal of interest.</h2><p>The goal is not only a cleaner image, but an accurate account of the activity that the image represents.</p></article><article><h2 class="section-title">Make methods useful in practice.</h2><p>I work on computational approaches that can be connected to experimental data and imaging workflows.</p></article></div></div></section><section class="section"><div class="container feature-grid two">'+feature('Research','See the methods and publications behind this direction.','research.html')+feature('Contact','Get in touch about research and scientific discussions.','contact.html','teal')+'</div></section>'
page('vision','Vision',vision,'Research direction: computational tools for reliable neural activity measurements.')
research=hero('What I do','Computational methods for neuroscience and imaging.','My research focuses on recovering information from noisy recordings and designing self-supervised methods that work with experimental data.')
research+='<section class="section"><div class="container split">'+figure()+'<div><p class="eyebrow">Approach</p><h2 class="section-title">Statistical models and neural networks, developed around the measurement.</h2><div class="numbered-point"><span>01</span><p>Use the spatial and temporal structure in imaging data to recover neural signals.</p></div><div class="numbered-point"><span>02</span><p>Design learning algorithms around the constraints of real data and computing hardware.</p></div></div></div></section>'
questions=[('denoising','How can fast neural activity be recovered without clean training images?'),('calcium','How can motion and neural activity be separated in calcium imaging?'),('learning','How can self-supervised methods become more computationally efficient?')]
research+='<section class="section gray"><div class="container"><p class="eyebrow blue-text">Key questions</p><div class="question-grid">'+''.join(f'<a class="question" href="research.html#{id}"><span class="eyebrow">0{i+1}</span><h2 class="section-title">{text}</h2><span class="arrow square">{ARROW}</span></a>' for i,(id,text) in enumerate(questions))+'</div></div></section>'
research+='<section class="section"><div class="container project-list"><article class="project" id="denoising"><div><p class="eyebrow blue-text">Self-supervised denoising</p><h2>Recovering neural activity</h2></div><div><h3>SUPPORT</h3><p>SUPPORT predicts a pixel from its spatial and temporal neighbours, excluding the target pixel. This allows voltage imaging data to be denoised without assuming that a fast event is present in adjacent frames.</p>'+link(SUPPORT,'Read the paper')+link('resources.html#support-code','Code and data')+'<h3>Multi-scale blind-spot networks</h3><p>U-BSN uses a U-Net-based architecture with design principles for J-invariant self-supervised denoising.</p>'+link(UBSN,'WACV 2025 paper')+'</div></article>'
research+='<article class="project" id="calcium"><div><p class="eyebrow blue-text">Calcium imaging</p><h2>Alignment and signal extraction</h2></div><div><h3>REALS</h3><p>REALS performs image alignment together with low-rank and sparse decomposition, separating motion from changing neuronal activity.</p>'+link(REALS,'WACV 2023 paper')+'<h3>Neural approximations of robust PCA</h3><p>Related work studies efficient neural-network approximations for automated calcium imaging analysis.</p>'+link('publications.html#robust-pca','MICCAI 2021 publication')+'</div></article>'
research+='<article class="project" id="learning"><div><p class="eyebrow blue-text">Learning and hardware</p><h2>Self-supervised video processing</h2></div><div><h3>Analogue computing</h3><p>This work implements self-supervised video processing with self-calibration on a selector-less memristor array.</p>'+link(MEMRISTOR,'Nature Electronics · 2025')+'<p class="body-copy">The connection between network design and computational cost also motivates the multi-scale denoising work.</p>'+link(UBSN,'Multi-scale network design')+'</div></article></div></section>'
research+='<section class="section gray"><div class="container feature-grid two">'+feature('Publications','Read the complete publication list.','publications.html')+feature('Resources','Software and datasets associated with the research.','resources.html','teal')+'</div></section>'
page('research','Research',research,'Research on SUPPORT, calcium imaging analysis, blind-spot networks, and analogue video processing.')
