publications=hero('Research','Publications','',selector)+'<section class="section"><div class="container"><p class="author-note">* Equal contribution · ** Co-corresponding authors</p><p class="sr-only" id="publication-count" aria-live="polite">16 publications</p><ol class="publication-list">'+''.join(items)+'</ol></div></section>'
page('publications','Publications',publications,'Journal articles, conference papers, and preprints by Seungjae Han.')
