resources+='<section class="section"><div class="container resource-list"><article id="support-code"><p class="eyebrow blue-text">Software</p><h2>SUPPORT</h2><p>The PyTorch implementation, installation instructions, and examples for SUPPORT.</p>'+link('https://github.com/NICALab/SUPPORT','Code and documentation','button-link')+'</article><article><p class="eyebrow blue-text">Data</p><h2>SUPPORT datasets</h2><p>Public imaging datasets accompanying the Nature Methods paper.</p>'+link('https://zenodo.org/records/8176722','Datasets on Zenodo','button-link')+'</article><article><p class="eyebrow blue-text">Publications</p><h2>Papers and supplementary material</h2><p>Publisher pages provide the articles and their associated supplementary files.</p>'+link('publications.html','Publication list','button-link')+'</article></div></section>'
