contact=hero('Contact','Get in touch.')+'<section class="section"><div class="container contact-grid"><div><h2>Seungjae Han, PhD</h2><p>Postdoctoral Fellow<br>School of Electrical Engineering<br>KAIST, South Korea</p>'+link('mailto:jay0118@kaist.ac.kr','jay0118@kaist.ac.kr','button-link')+'</div><div><p class="eyebrow blue-text">Research and background</p>'+link(SCHOLAR,'Google Scholar','contact-row')+link('https://github.com/SteveJayH','GitHub','contact-row')+link('CV_SeungjaeHan_0707.pdf','Curriculum Vitae','contact-row')+link('profile.html','Biography','contact-row')+'</div></div></section>'
